#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

struct Point {
    double x, y;
};

/* Count the number of cartesian points in each quadrant. The vector points contains a list of `Point` objects.
   Store the counts in `bins`.
   Use OpenMP to count in parallel.
   Example:

   input: [{x=1.5, y=0.1}, {x=-3, y=1.1}, {x=5, y=9}, {x=1.5, y=-1}, {x=3, y=-7}, {x=0.1, y=2}]
   output: [3, 1, 0, 2]
*/
void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0, 0, 0, 0};

    const std::size_t n = points.size();

    #pragma omp parallel for reduction(+:bins[:4]) schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        const double x = points[i].x;
        const double y = points[i].y;

        if (x > 0.0 && y > 0.0) {
            bins[0] += 1; // Quadrant I
        } else if (x < 0.0 && y > 0.0) {
            bins[1] += 1; // Quadrant II
        } else if (x < 0.0 && y < 0.0) {
            bins[2] += 1; // Quadrant III
        } else if (x > 0.0 && y < 0.0) {
            bins[3] += 1; // Quadrant IV
        }
        // Points on axes (x == 0 or y == 0) are ignored.
    }
}
